// ── WF2: Validar entrega recibida por webhook ─────────────────────────────
const body = $json.body || $json;
const errors = [];
const required = ['student_id', 'student_name', 'task_id', 'task_name', 'deadline', 'file_name', 'file_extension'];
required.forEach(f => { if (!body[f]) errors.push('Campo requerido: ' + f); });
if (errors.length > 0) {
  return [{ json: { valid: false, errors, status: 'validation_error' } }];
}
const allowedExts = ['pdf', 'docx', 'doc', 'zip', 'py', 'java', 'cpp', 'txt', 'xlsx'];
const ext = (body.file_extension || '').toLowerCase().replace('.', '');
const isValidExt = allowedExts.includes(ext);
const deadline = new Date(body.deadline);
const now = new Date();
const isLate = now > deadline;
const minutesLate = isLate ? Math.round((now - deadline) / 60000) : 0;
let submissionStatus;
if (!isValidExt) submissionStatus = 'invalid_format';
else if (isLate) submissionStatus = 'late';
else submissionStatus = 'on_time';
const studentEmail = body.student_email || ('estudiante.' + body.student_id.toLowerCase() + '@academico.local');
return [{
  json: {
    ...body,
    valid: isValidExt,
    isLate,
    minutesLate,
    submissionStatus,
    submissionDate: now.toISOString(),
    studentEmail,
    ext
  }
}];

// ── WF2: Construir SQL para insertar entrega ──────────────────────────────
const safe = s => String(s||'').replace(/'/g,"''");
const j = $json;
const sql_query =
  "INSERT INTO task_submissions (student_id, student_name, task_id, task_name, submission_date, deadline, status, file_name, file_extension, is_late) VALUES (" +
  "'" + safe(j.student_id) + "'," +
  "'" + safe(j.student_name) + "'," +
  "'" + safe(j.task_id) + "'," +
  "'" + safe(j.task_name) + "'," +
  "'" + safe(j.submissionDate) + "'," +
  "'" + safe(j.deadline) + "'," +
  "'" + safe(j.submissionStatus) + "'," +
  "'" + safe(j.file_name) + "'," +
  "'" + safe(j.ext) + "'," +
  (j.isLate ? 'TRUE' : 'FALSE') +
  ") RETURNING id";
return [{ json: { ...$json, sql_query } }];

// ── WF2: Preparar email de alerta por tardanza ────────────────────────────
const j = $json;
const hrs  = Math.floor(j.minutesLate / 60);
const mins = j.minutesLate % 60;
const delay = hrs > 0 ? hrs + 'h ' + mins + 'min' : mins + 'min';
const emailSubject = '⚠️ Entrega Tardía: ' + j.task_name + ' — ' + j.student_name;
const emailBody = `
<div style="font-family:'Segoe UI',Arial,sans-serif;max-width:560px;margin:0 auto">
  <div style="background:linear-gradient(135deg,#dc2626,#ef4444);color:#fff;padding:20px 24px;border-radius:10px 10px 0 0">
    <h2 style="margin:0">⚠️ Alerta: Entrega Tardía</h2>
  </div>
  <div style="background:#fff;padding:24px;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 10px 10px">
    <p>Estimado/a <strong>${j.student_name}</strong>,</p>
    <p style="margin-top:12px">Su entrega fue recibida <strong style="color:#dc2626">${delay} después</strong> del plazo establecido.</p>
    <table style="width:100%;border-collapse:collapse;margin:16px 0;font-size:14px">
      <tr style="background:#fef2f2"><td style="padding:8px 12px;font-weight:600;color:#991b1b">Tarea:</td><td style="padding:8px 12px">${j.task_name}</td></tr>
      <tr><td style="padding:8px 12px;font-weight:600;color:#991b1b">Archivo:</td><td style="padding:8px 12px">${j.file_name}.${j.ext}</td></tr>
      <tr style="background:#fef2f2"><td style="padding:8px 12px;font-weight:600;color:#991b1b">Plazo:</td><td style="padding:8px 12px">${j.deadline}</td></tr>
      <tr><td style="padding:8px 12px;font-weight:600;color:#991b1b">Recibido:</td><td style="padding:8px 12px">${j.submissionDate}</td></tr>
    </table>
    <p style="color:#6b7280;font-size:13px">Esta entrega será revisada con penalización por atraso según la política del curso.</p>
  </div>
</div>`;
const safe = s => String(s||'').replace(/'/g,"''");
const notif_sql = "INSERT INTO notifications_log (student_id, notification_type, message, status) VALUES ('" +
  safe(j.student_id) + "', 'late_submission', 'Tardanza " + delay + " en " + safe(j.task_name) + "', 'sent')";
return [{ json: { ...j, emailSubject, emailBody, notif_sql } }];

// ── WF2: Respuesta notificación tardanza ─────────────────────────────────
const j = $json;
return [{
  json: {
    success: true,
    status: 'late',
    message: 'Entrega recibida con ' + j.minutesLate + ' minutos de atraso ⚠️ — Se ha enviado notificación.',
    student_id: j.student_id,
    task_id: j.task_id,
    submissionDate: j.submissionDate,
    notificationSent: true
  }
}];

// ── WF2: Respuesta OK (entrega a tiempo) ─────────────────────────────────
const j = $json;
return [{
  json: {
    success: true,
    status: j.submissionStatus,
    message: j.submissionStatus === 'on_time'
      ? 'Entrega recibida correctamente y dentro del plazo ✅'
      : 'Entrega con formato inválido ❌',
    student_id: j.student_id,
    task_id: j.task_id,
    submissionDate: j.submissionDate
  }
}];
